<?php
declare(strict_types=1);
$root='';$project='';$dataform='';$file='';foreach(array_slice($argv,1) as $a){if(str_starts_with($a,'--root='))$root=substr($a,7);elseif(str_starts_with($a,'--project='))$project=substr($a,10);elseif(str_starts_with($a,'--dataform='))$dataform=substr($a,11);elseif(str_starts_with($a,'--definition='))$file=substr($a,13);}if($root===''||$project===''||$dataform===''||$file===''||!is_file($file)){fwrite(STDERR,"Usage: php publish_dataform_definition.php --root=D:\\xampp\\htdocs\\enterpriseManager --project=1 --dataform=1 --definition=definition.json\n");exit(2);}require rtrim($root,'/\\').'/system/licensing/Autoload.php';require_once rtrim($root,'/\\').'/system/licensing/LicenseConfigStore.php';$cfg=EnterpriseLicenseConfigStore::load($root);$def=json_decode((string)file_get_contents($file),true);if(!is_array($def)){fwrite(STDERR,"Definition JSON invalid\n");exit(3);} $api=new \EasyIT\Enterprise\Licensing\LicenseApiClient($cfg);$client=new \EasyIT\Enterprise\Licensing\DataFormDesignerClient($api);$validation=$client->validate($project,$dataform,$def);if(empty($validation['valid'])){echo json_encode($validation,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;exit(4);} $compiled=$client->compile($project,$dataform,$def);if(empty($compiled['compiled'])||empty($compiled['definition_id'])){echo json_encode($compiled,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;exit(5);} $published=$client->publish((string)$compiled['definition_id'],$project,$dataform);echo json_encode(['validation'=>$validation,'compiled'=>$compiled,'published'=>$published],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).PHP_EOL;
